/* 无限小说网 sjxs5.org 书源 jsLib v1 —— 纯 ES5 */
var KB_STATUS = {
    '連載中': '连载', '连载中': '连载', '連載': '连载', '连载': '连载',
    '已完結': '完结', '已完结': '完结', '完結': '完结', '完结': '完结', '全本': '完结', '完本': '完结',
    '休載中': '休刊', '斷更': '断更'
};
var KB_T2S = {
    '仙俠': '仙侠', '武俠': '武侠', '歷史': '历史', '軍事': '军事', '科幻': '科幻',
    '懸疑': '悬疑', '靈異': '灵异', '網遊': '网游', '輕小說': '轻小说', '現代': '现代',
    '穿越': '穿越', '重生': '重生', '系統': '系统', '校園': '校园', '熱血': '热血',
    '修真': '修真', '奇幻': '奇幻', '都市': '都市', '玄幻': '玄幻', '言情': '言情'
};
function kbTrim(s){return String(s===null||s===undefined?'':s).replace(/^[\s\u00a0\u3000]+|[\s\u00a0\u3000]+$/g,'');}
function kbEsc(s){return String(s===null||s===undefined?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function kbUnescape(s){
    var t=String(s===null||s===undefined?'':s);
    t=t.replace(/&nbsp;/gi,' ').replace(/&ensp;/gi,' ').replace(/&emsp;/gi,'\u3000');
    t=t.replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&apos;/gi,"'").replace(/&#39;/g,"'").replace(/&amp;/gi,'&');
    t=t.replace(/&#x([0-9a-f]+);/gi,function(m,h){return String.fromCharCode(parseInt(h,16));});
    t=t.replace(/&#(\d+);/g,function(m,d){return String.fromCharCode(parseInt(d,10));});
    return t;
}
function kbT2S(s){var out=String(s===null||s===undefined?'':s),k;for(k in KB_T2S){if(KB_T2S.hasOwnProperty(k)&&out.indexOf(k)>-1)out=out.split(k).join(KB_T2S[k]);}return out;}
function kbStatus(v){var t=kbTrim(v);if(!t)return '';if(KB_STATUS[t])return KB_STATUS[t];if(/完结|完本|全本/.test(t))return '完结';if(/连载|連載|未完/.test(t))return '连载';return t;}
function kbWordsNum(w){var n=parseInt(String(w===null||w===undefined?'':w).replace(/[^\d]/g,''),10);if(!n)return '';if(n>=100000000)return (n/100000000).toFixed(1).replace(/\.0$/,'')+'亿字';if(n>=10000)return (n/10000).toFixed(1).replace(/\.0$/,'')+'万字';return n+'字';}
function kbText(html){
    var t=String(html===null||html===undefined?'':html);
    t=t.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'');
    t=t.replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|h[1-6]|li|tr)>/gi,'\n').replace(/<[^>]+>/g,'');
    t=kbUnescape(t).replace(/\r\n?/g,'\n').replace(/\n{3,}/g,'\n\n');
    return t;
}
var KB_AD_LINE=[
    /^请记住本书首发域名/i,/^本站域名/i,/^最新网址/i,/^手机版阅读网址/i,
    /^笔趣阁/,/^www\./i,/^https?:\/\//i,/^m\./i,
    /一秒记住/,/无弹窗/,/全文阅读/,/最新章节/,/加入书签/,/投推荐票/,
    /求月票/,/求收藏/,/求订阅/,/求推荐/,/本章未完.{0,10}点击下一页/,/点击下一页继续阅读/,
    /^记住网址/,/^手机用户请浏览/,/^章节错误.{0,10}举报/,/^AD$/i,
    /无限小说网提供/,/请到.{0,10}阅读/
];
function kbAdClean(s){
    var t=String(s===null||s===undefined?'':s),lines=t.split(/\n/),out=[],i,k,line,hit;
    for(i=0;i<lines.length;i++){
        line=kbTrim(lines[i]);
        if(!line){out.push('');continue;}
        if(line.length>60){out.push(line);continue;}
        hit=false;
        for(k=0;k<KB_AD_LINE.length;k++){if(KB_AD_LINE[k].test(line)){hit=true;break;}}
        if(hit)continue;
        out.push(line);
    }
    return out.join('\n');
}
function kbPara(text){
    var t=String(text===null||text===undefined?'':text);
    t=t.replace(/\r\n?/g,'\n').replace(/[\u200b\u200c\u200d\ufeff]/g,'').replace(/\u00a0/g,' ');
    var lines=t.split('\n'),out=[],i,line;
    for(i=0;i<lines.length;i++){
        line=lines[i].replace(/^[\s\u3000\u00a0]+/,'').replace(/[\s\u3000\u00a0]+$/,'');
        if(!line||line.length<2)continue;
        out.push('<p>'+kbEsc(line)+'</p>');
    }
    if(!out.length)return '<p>△ 本章内容为空，可能为付费章节</p>';
    return out.join('\n');
}
var KB_IND='\u3000\u3000';
function kbIndentParas(text){
    var t=String(text===null||text===undefined?'':text);
    t=t.replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|h[1-6]|li|tr)>/gi,'\n').replace(/<[^>]+>/g,'');
    t=kbUnescape(t).replace(/\r\n?/g,'\n');
    var lines=t.split('\n'),out=[],i,l;
    for(i=0;i<lines.length;i++){
        l=kbTrim(lines[i]);
        if(!l||l.length<2)continue;
        out.push(KB_IND+l);
    }
    return out.join('\n');
}

/* ===== 站点专用：URL 与解析 ===== */
function sjAbs(path){
    var p=String(path===null||path===undefined?'':path);
    if(/^https?:\/\//i.test(p))return p;
    if(p.charAt(0)==='/')return 'http://www.sjxs5.org'+p;
    return 'http://www.sjxs5.org/'+p;
}
function sjBookId(url){
    var m=String(url===null||url===undefined?'':url).match(/\/txt(\d+)\.html/);
    if(m)return m[1];
    m=String(url).match(/\/read\/(\d+)/);
    return m?m[1]:'';
}
// 从 HTML 抠 <div id="booktxt">…</div> 里的纯文本段落
function sjBooktxt(html){
    var h=String(html===null||html===undefined?'':html);
    var i=h.indexOf('id="booktxt"');
    if(i<0)i=h.indexOf("id='booktxt'");
    if(i<0)return '';
    var s=h.indexOf('>',i);
    var e=h.indexOf('</div>',s);
    if(s<0||e<0)return '';
    return h.substring(s+1,e);
}
// 判断某页 HTML 是否还有下一页（正文分页 _N）
function sjHasNextContent(html){
    var h=String(html===null||html===undefined?'':html);
    var m=h.match(/<a[^>]*rel="next"[^>]*href="([^"]+)"[^>]*>/i);
    if(m && /\/read\/\d+\/\d+_\d+\.html/.test(m[1]))return m[1];
    // 兜底：任意 href 里找 _N.html
    m=h.match(/href="(\/read\/\d+\/\d+_\d+\.html)"/i);
    return m?m[1]:'';
}
// 正文：抓当前页 + 全部后续分 page，拼接后分段输出
function sjContentHtml(baseUrl, java){
    var url=String(baseUrl===null||baseUrl===undefined?'':baseUrl).split(',{')[0];
    var all='',seen={},guard=0;
    while(url && guard<40){
        guard++;
        if(seen[url])break;
        seen[url]=1;
        var html='';
        try{html=String(java.ajax(sjAbs(url))||'');}catch(e){break;}
        if(!html)break;
        var seg=sjBooktxt(html);
        if(seg)all+=seg+'\n';
        var nx=sjHasNextContent(html);
        if(!nx)break;
        url=nx;
    }
    if(!all)return '<p>△ 正文获取失败</p>';
    return kbPara(kbAdClean(kbText(all)));
}
// 从目录页找"下一页"：取所有 _N.html 里页码最大的那个（避开上一页链接）
function sjTocNext(html){
    var h=String(html===null||html===undefined?'':html);
    // 优先取「下一页」按钮
    var m=h.match(/<a[^>]*class="[^"]*index-container-btn[^"]*"[^>]*href="(\/read\/\d+_\d+\.html)"[^>]*>[^<]*下一页/i);
    if(m)return m[1];
    m=h.match(/href="(\/read\/\d+_\d+\.html)"[^>]*>[^<]*下一页/i);
    if(m)return m[1];
    // 兜底：所有 _N 里取页码最大
    var all=h.match(/\/read\/\d+_\d+\.html/g)||[],best='',max=0,i,mm,pn;
    for(i=0;i<all.length;i++){
        mm=all[i].match(/_(\d+)\.html/);
        if(mm){pn=parseInt(mm[1],10);if(pn>max){max=pn;best=all[i];}}
    }
    return best;
}
// 目录：抓当前页 + 全部后续页，产自建 HTML 供 CSS 取
function sjTocHtml(html, baseUrl, java){
    var first=String(html===null||html===undefined?'':html);
    var b=String(baseUrl===null||baseUrl===undefined?'':baseUrl).split(',{')[0];
    var bid=sjBookId(b);
    if(!bid){var m=first.match(/\/read\/(\d+)/);bid=m?m[1]:'';}
    var pages=[first],url='',seen={},guard=0;
    url=sjTocNext(first);
    while(url && guard<60){
        guard++;
        if(seen[url])break;
        seen[url]=1;
        var h='';
        try{h=String(java.ajax(sjAbs(url))||'');}catch(e){break;}
        if(!h)break;
        pages.push(h);
        url=sjTocNext(h);
        // 若下一页已被抓过则停（页码回退保护）
        if(seen[url])break;
    }
    var out=[],i,j,rows;
    for(i=0;i<pages.length;i++){
        // 章节区：<div id="content_N"> 里的 <a ...><dd>章名</dd></a>
        rows=pages[i].match(/<a[^>]*href="(\/read\/\d+\/\d+\.html)"[^>]*>\s*<dd>([\s\S]*?)<\/dd>\s*<\/a>/gi)||[];
        for(j=0;j<rows.length;j++){
            var rm=rows[j].match(/href="([^"]+)"/i);
            var nm=rows[j].match(/<dd>([\s\S]*?)<\/dd>/i);
            if(rm&&nm){
                var name=kbTrim(kbUnescape(nm[1].replace(/<[^>]+>/g,'')));
                if(name)out.push('<div class="sj-c"><a href="'+kbEsc(sjAbs(rm[1]))+'">'+kbEsc(name)+'</a></div>');
            }
        }
    }
    if(!out.length)return '<div class="sj-c"><a href="#">目录获取失败</a></div>';
    return out.join('\n');
}

// 封面：nocover 占位图视为空
function sjCover(u){
    var s=String(u===null||u===undefined?'':u);
    if(!s||/nocover/i.test(s))return '';
    return s;
}
// 详情页字数：从整页 HTML 精确抠「字数：366 万字」或「366 万字」
function sjWords(v){
    var s=String(v===null||v===undefined?'':v);
    var m=s.match(/字数[：:]\s*([\d.]+)\s*万/);
    if(!m)m=s.match(/([\d.]+)\s*万字/);
    if(m)return kbWordsNum(Math.round(parseFloat(m[1])*10000));
    return kbWordsNum(s);
}
// 详情页连载状态：从整页抠「状态：连载」
function sjStatus(v){
    var s=String(v===null||v===undefined?'':v);
    var m=s.match(/状态[：:]\s*([^<\s|]+)/);
    return m?kbStatus(m[1]):'';
}

// tocUrl：优先从详情页 HTML 的 canonical 抠书号，兜底用 baseUrl
function sjTocUrl(html, baseUrl){
    var h=String(html===null||html===undefined?'':html);
    var m=h.match(/\/txt(\d+)\.html/);
    if(!m)m=h.match(/\/read\/(\d+)/);
    var id=m?m[1]:sjBookId(baseUrl);
    return id?('http://www.sjxs5.org/read/'+id+'.html'):'';
}
